import 'dart:async';
import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';
import 'package:centria/theme/app_theme.dart';
import 'package:centria/services/auth_state.dart';

// In-memory 184x184 crisp logo bytes (2x resolution of 92x92) for instantaneous frame-1 rendering
final Uint8List _kLogoBytes = base64Decode(
  '',
);

class SplashScreen extends StatefulWidget {
  const SplashScreen({super.key});

  @override
  State<SplashScreen> createState() => _SplashScreenState();
}

class _SplashScreenState extends State<SplashScreen> {
  int _dotIndex = 0;
  Timer? _dotTimer;

  @override
  void initState() {
    super.initState();
    _dotTimer = Timer.periodic(const Duration(milliseconds: 200), (t) {
      if (mounted) {
        setState(() {
          _dotIndex = (_dotIndex + 1) % 3;
        });
      }
    });

    _navigateAfterDelay();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // Precache asset image for subsequent screens (homepage, app shell)
    precacheImage(const AssetImage('assets/images/logo.png'), context);
  }

  Future<void> _navigateAfterDelay() async {
    // 0.8s splash duration for smooth branded intro
    await Future.delayed(const Duration(milliseconds: 800));
    await AuthState().init();

    if (!mounted) return;
    _dotTimer?.cancel();

    // Determine target route
    String target = Uri.base.path;
    if (target.isEmpty || target == '/splash') {
      target = AuthState().isAuthenticated ? '/dashboard' : '/';
    } else if (!AuthState().isAuthenticated && target != '/') {
      target = '/';
    }

    Navigator.pushReplacementNamed(context, target);
  }

  @override
  void dispose() {
    _dotTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppColors.paper,
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // Centria Logo - renders instantaneously from memory without network latency
            ClipRRect(
              borderRadius: BorderRadius.circular(20),
              child: Image.memory(
                _kLogoBytes,
                width: 92,
                height: 92,
                gaplessPlayback: true,
                filterQuality: FilterQuality.medium,
                errorBuilder: (context, error, stackTrace) => Image.asset(
                  'assets/images/logo.png',
                  width: 92,
                  height: 92,
                  gaplessPlayback: true,
                ),
              ),
            ),
            // Centria Name (no space between logo and name)
            Text(
              'Centria',
              style: GoogleFonts.inter(
                fontSize: 32,
                fontWeight: FontWeight.w700,
                letterSpacing: -1.2,
                color: AppColors.ink,
              ),
            ),
            const SizedBox(height: 16),
            // 3 Animated Dots
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: List.generate(3, (index) {
                final isActive = index == _dotIndex;
                return AnimatedContainer(
                  duration: const Duration(milliseconds: 200),
                  margin: const EdgeInsets.symmetric(horizontal: 4),
                  width: isActive ? 9 : 7,
                  height: isActive ? 9 : 7,
                  decoration: BoxDecoration(
                    color: isActive ? AppColors.teal : AppColors.line,
                    shape: BoxShape.circle,
                  ),
                );
              }),
            ),
          ],
        ),
      ),
    );
  }
}
